const aliases = {storefront:'store','arrow-counter-clockwise':'refresh',sparkle:'sparkles', 'shopping-cart':'cart','shopping-cart-simple':'cart','chart-line-up':'chart-line','shield-check':'shield','file-text':'file','chat':'message','whatsapp':'message','whatsapp-logo':'message', 'handshake':'users','hourglass':'clock','hourglass-medium':'clock','currency-inr':'rupee','phone-call':'phone','envelope':'mail','envelope-simple':'mail','airplane':'plane','airplane-tilt':'plane','books':'book','gear':'settings','caret-down':'chevron-down','arrow-up-right':'arrow-right','chart':'chart-line'};
export function icon(name, size = 18) { name=String(name||'sparkles').replace(/^ph-/, ''); name=aliases[name]||name; return `<svg class="icon" width="${Number(size)||18}" height="${Number(size)||18}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.sparkles}</svg>`; }
export function button(label, action, variant='secondary', attrs='') { return `<button type="button" class="btn btn-${esc(variant)}" data-action="${esc(action)}" ${attrs}>${label}</button>`; }
export function badge(label,tone='neutral') { return `<span class="badge badge-${esc(tone)}">${esc(label)}</span>`; }
export function field(label,input,hint='') { return `<label class="field"><span class="field-label">${esc(label)}</span>${input}${hint?`<span class="field-hint">${esc(hint)}</span>`:''}</label>`; }
export function empty(title,desc='',action='') { return `<div class="empty">${icon('check-circle',40)}<h3>${esc(title)}</h3><p class="muted">${esc(desc)}</p>${action}</div>`; }
